<?php
namespace App\Http\Controllers; use App\Models\{Room,RoomType}; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class RoomController extends Controller { public function index(Request $r){$pid=$r->user()->property_id;$rooms=Room::with('roomType')->where('property_id',$pid)->orderBy('room_number')->paginate(20);$types=RoomType::where('property_id',$pid)->where('is_active',true)->orderBy('name')->get();return view('rooms.index',compact('rooms','types'));} public function store(Request $r){$pid=$r->user()->property_id;$d=$r->validate(['room_type_id'=>['required',Rule::exists('room_types','id')->where('property_id',$pid)],'room_number'=>['required','max:50',Rule::unique('rooms')->where(fn($q)=>$q->where('property_id',$pid))],'name'=>'nullable|max:100','building'=>'nullable|max:100','floor'=>'nullable|max:50','status'=>'required|max:30','housekeeping_status'=>'required|max:30','notes'=>'nullable|max:1000']);Room::create($d+['property_id'=>$pid,'is_active'=>true]);return back()->with('success','Room created successfully.');} public function update(Request $r,Room $room){abort_unless($room->property_id===$r->user()->property_id,404);$d=$r->validate(['room_type_id'=>'required|exists:room_types,id','room_number'=>['required','max:50',Rule::unique('rooms')->ignore($room)->where(fn($q)=>$q->where('property_id',$room->property_id))],'name'=>'nullable|max:100','building'=>'nullable|max:100','floor'=>'nullable|max:50','status'=>'required|max:30','housekeeping_status'=>'required|max:30','notes'=>'nullable|max:1000']);$room->update($d);return back()->with('success','Room updated successfully.');} }
